class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is EnvironmentKindMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is EntitlementSourceMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is LogLevelMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is CardioLanguageMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is ProgressBarPositionMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    } else if (value is CardioScanFailureKindMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    } else if (value is CardioTestStepMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.index);
    } else if (value is EnvironmentMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is InitializeRequest) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is CardioErrorMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is AvailabilityMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is CardioPaletteMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is CardioStyleMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is InstructionItemMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is InstructionTranslationMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is CardioTestOptionsMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is BloodPressureMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is CardioResultMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else if (value is CardioScanFailureMessage) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    } else if (value is CardioTestOutcomeMessage) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    } else if (value is CardioTestStatusMessage) {
      buffer.putUint8(149);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : EnvironmentKindMessage.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : EntitlementSourceMessage.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : LogLevelMessage.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : CardioLanguageMessage.values[value];
      case 133:
        final value = readValue(buffer) as int?;
        return value == null ? null : ProgressBarPositionMessage.values[value];
      case 134:
        final value = readValue(buffer) as int?;
        return value == null ? null : CardioScanFailureKindMessage.values[value];
      case 135:
        final value = readValue(buffer) as int?;
        return value == null ? null : CardioTestStepMessage.values[value];
      case 136:
        return EnvironmentMessage.decode(readValue(buffer)!);
      case 137:
        return InitializeRequest.decode(readValue(buffer)!);
      case 138:
        return CardioErrorMessage.decode(readValue(buffer)!);
      case 139:
        return AvailabilityMessage.decode(readValue(buffer)!);
      case 140:
        return CardioPaletteMessage.decode(readValue(buffer)!);
      case 141:
        return CardioStyleMessage.decode(readValue(buffer)!);
      case 142:
        return InstructionItemMessage.decode(readValue(buffer)!);
      case 143:
        return InstructionTranslationMessage.decode(readValue(buffer)!);
      case 144:
        return CardioTestOptionsMessage.decode(readValue(buffer)!);
      case 145:
        return BloodPressureMessage.decode(readValue(buffer)!);
      case 146:
        return CardioResultMessage.decode(readValue(buffer)!);
      case 147:
        return CardioScanFailureMessage.decode(readValue(buffer)!);
      case 148:
        return CardioTestOutcomeMessage.decode(readValue(buffer)!);
      case 149:
        return CardioTestStatusMessage.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

